package migratebacklogs

import (
	"strings"
	"testing"
)

// TestGoldenReplay runs every parity case through the port and compares it with what the FROZEN legacy script
// produced (testdata/golden/cases.json, regenerated by TestDifferential). It carries no build tag, so gremlins'
// -tags nodiff builds still kill mutants without bash.
func TestGoldenReplay(t *testing.T) {
	golden := readGoldens(t)
	cases := allCases()
	for _, c := range cases {
		want, ok := golden[c.name]
		if !ok {
			t.Errorf("%s: no golden (regenerate with MIGRATE_BACKLOGS_UPDATE=1 go test -run TestDifferential)", c.name)
			continue
		}
		t.Run(c.name, func(t *testing.T) {
			t.Parallel()
			root, corpus := c.layout(t)
			if d := diffResult(want, runGo(t, root, corpus, c.resolveArgs(root, corpus))); d != "" {
				t.Errorf("Go differs from the recorded legacy output:\n%s", d)
			}
		})
	}
	if len(golden) != len(cases) {
		t.Errorf("%d goldens for %d cases: regenerate to drop the stale ones", len(golden), len(cases))
	}
}

func TestCaseNamesAreUnique(t *testing.T) {
	seen := map[string]bool{}
	for _, c := range allCases() {
		if seen[c.name] {
			t.Errorf("duplicate case name %q", c.name)
		}
		seen[c.name] = true
	}
}

// typedLines are the line prefixes the tool prints. Every one is shown by at least one recorded case (CLAUDE.md
// section 7: a state that no golden shows can change unnoticed).
var typedLines = []string{
	"PROPOSE ", "ok ", "empty-input: ", "absent-input: no RESEARCH-STATE", "absent-input: ", "usage: ", "migrate-backlogs: ",
	"MANUAL ", "--- a/", "+++ b/", "@@ ", `\ No newline at end of file`,
}

func TestGoldensCoverEveryTypedLine(t *testing.T) {
	golden := readGoldens(t)
	for _, prefix := range typedLines {
		found := false
		for _, r := range golden {
			for _, l := range strings.Split(r.Stdout+r.Stderr, "\n") {
				found = found || strings.HasPrefix(l, prefix)
			}
		}
		if !found {
			t.Errorf("no golden prints a line starting with %q", prefix)
		}
	}
	for _, reason := range allReasons {
		found := false
		for _, r := range golden {
			found = found || strings.Contains(r.Stdout, " "+reason+" rows=")
		}
		if !found {
			t.Errorf("no golden prints the MANUAL reason %q", reason)
		}
	}
}
